import { unstable_cache } from 'next/cache'

// In-memory stand-in for the upstream ERP/PIM source of truth.
// In a real app this state lives in a database; syncCatalog() pulls fresh
// values from the ERP into it.
let erpData = [
  { id: 1, name: 'Laptop', price: 999, stock: 12 },
  { id: 2, name: 'Phone', price: 699, stock: 30 },
  { id: 3, name: 'Tablet', price: 499, stock: 18 },
  { id: 4, name: 'Headphones', price: 199, stock: 50 },
  { id: 5, name: 'Watch', price: 299, stock: 25 },
]

let lastSyncedAt = null

export async function getAllProducts() {
  // Simulate database delay so caching is visibly worthwhile on a read-heavy page.
  await new Promise((resolve) => setTimeout(resolve, 100))

  return erpData.map((p) => ({ ...p }))
}

// Catalog read served from the data cache, tagged "products" so a sync can
// invalidate every view that depends on this catalog in one call.
// revalidate: false => the entry never expires by time; it is only refreshed
// when the "products" tag is revalidated after a sync.
export const getCachedProducts = unstable_cache(
  async () => {
    const products = await getAllProducts()
    return { products, lastSyncedAt }
  },
  ['products'],
  { tags: ['products'], revalidate: false }
)

// Pull the latest pricing, inventory and availability from the upstream
// ERP/PIM. Simulates a heavy job that can touch thousands of SKUs, so the
// admin action never awaits this directly.
export async function syncCatalog() {
  await new Promise((resolve) => setTimeout(resolve, 1200))

  erpData = erpData.map((p) => ({
    ...p,
    price: Math.max(1, Math.round(p.price * (0.95 + Math.random() * 0.1))),
    stock: Math.floor(Math.random() * 100),
  }))
  lastSyncedAt = new Date().toISOString()
}

import { after, revalidateTag } from 'next/server'

import { getCachedProducts, syncCatalog } from '@/lib/db'
import { SyncButton } from './sync-button'

// The catalog is read-heavy: render on every visit so admins always see the
// current cache state, while getCachedProducts() keeps the data fetch itself
// off the request path (served from the "products" data cache).
export const dynamic = 'force-dynamic'

export default async function Page() {
  // Inline Server Action bound to a regular HTML <form> below. It returns right
  // away: the heavy ERP/PIM sync runs after the response is sent via after(),
  // then the "products" cache tag is revalidated so every catalog view refreshes
  // in the background (stale-while-revalidate) instead of blocking this request.
  async function syncCatalogAction() {
    'use server'
    after(async () => {
      await syncCatalog()
      revalidateTag('products', 'max')
    })
  }

  const { products, lastSyncedAt } = await getCachedProducts()

  return (
    <main>
      <header>
        <div>
          <h1>Product Catalog</h1>
          <p className="muted">
            Reads are served from cache. Syncing refreshes the catalog in the
            background — you can keep working while it catches up.
          </p>
          <p className="muted">Last synced: {lastSyncedAt ?? 'never'}</p>
        </div>
        <form action={syncCatalogAction}>
          <SyncButton />
        </form>
      </header>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
            <th>Stock</th>
          </tr>
        </thead>
        <tbody>
          {products.map((p) => (
            <tr key={p.id}>
              <td>{p.id}</td>
              <td>{p.name}</td>
              <td>${p.price}</td>
              <td>{p.stock}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

