input.content:
import { unstable_cache } from 'next/cache'

let erpData = [
  { id: 1, name: 'Laptop', price: 999, stock: 12 },
  { id: 2, name: 'Phone', price: 699, stock: 30 },
  { id: 3, name: 'Tablet', price: 499, stock: 18 },
  { id: 4, name: 'Headphones', price: 199, stock: 50 },
  { id: 5, name: 'Watch', price: 299, stock: 25 },
]

let lastSyncedAt = null

export async function getAllProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))

  return erpData.map((p) => ({ ...p }))
}

export const getCachedProducts = unstable_cache(
  async () => {
    const products = await getAllProducts()
    return { products, lastSyncedAt }
  },
  ['products'],
  { tags: ['products'], revalidate: false }
)

export async function syncCatalog() {
  await new Promise((resolve) => setTimeout(resolve, 1200))

  erpData = erpData.map((p) => ({
    ...p,
    price: Math.max(1, Math.round(p.price * (0.95 + Math.random() * 0.1))),
    stock: Math.floor(Math.random() * 100),
  }))
  lastSyncedAt = new Date().toISOString()
}

